mapper.sql:
select s.*,
       coalesce(files.file_count, 0) as file_count,
       coalesce(files.total_size_bytes, 0) as total_size_bytes
from file_storage_space s force index (idx_file_storage_space_tenant_deleted_default_id)
left join (
    select bucket, count(1) as file_count, sum(file_size) as total_size_bytes
    from file_object force index (idx_file_object_tenant_deleted_bucket)
    where tenant_id = #{tenantId} and deleted = 0
    group by bucket
) files on files.bucket = s.storage_key

mapper.select:

where s.tenant_id = #{tenantId}
  and s.deleted = 0
order by s.default_flag desc, s.id asc
limit #{limit} offset #{offset}


where s.tenant_id = #{tenantId}
  and s.storage_key = #{storageKey}
  and s.deleted = 0


where s.tenant_id = #{tenantId}
  and s.id = #{id}
  and s.deleted = 0

select retain_file_on_record_delete
from file_storage_space
where tenant_id = #{tenantId}
  and storage_key = #{storageKey}
  and deleted = 0
limit 1

select access_key_secret
from file_storage_space
where id = #{id}
  and tenant_id = #{tenantId}
limit 1
